-- Généré par scripts/import-fff.js depuis data/coupes-2026-fff.json (epreuves.fff.fr (pages « Le match »), relevé du 29/09/2026 ; noms complets : convocation Seniors du 27/09/2026 + relevés précédents)
-- Ne pas exécuter deux fois.
select m.competition, m.home_name, m.away_name,
  (select count(*) from public.events e where e.match_id = m.id and e.k = 'goal' and e.t = 'H') || ' – ' ||
  (select count(*) from public.events e where e.match_id = m.id and e.k = 'goal' and e.t = 'A') as score,
  (select count(*) from public.events e where e.match_id = m.id) as actions
from public.matches m where m.id in ('29465383-8a75-41ca-bf86-e18f6b31eb57', 'c641ab8f-4670-496d-ac95-b2772582848f', '5cb18db4-bfb6-491f-a9a8-24da55db585e', '4c02bffa-09d9-45bd-96ef-5f17933b6487', '536f4aa6-abe3-4792-bb9a-ac6933d48c8d', '9b5abd99-cf6b-437e-878d-88e09bb1fa01', '04a2942c-e22a-4fad-93b1-476407ee5bfe', '3dcb80b2-214b-4d24-9423-fb3d64cf17e5') order by m.equipe;
-- J2 : noms complets trouvés sur les feuilles de Coupe de France
update public.matches set rosters = replace(replace(rosters::text, '"Perig C."', '"Perig Chouard"'), '"Alexis H."', '"Alexis Huret"')::jsonb
where equipe = 1 and competition = 'Régional 3 · J2';
